package log

import (
	"encoding/binary"
	"fmt"
	"hash/crc32"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

// The prefix-truncation point lives in its own sidecar
// ("truncate.idx"), deliberately separate from the rebuildable
// index.idx: index.idx is pure cache and may be deleted at any time,
// but the truncation point is the only record that historical
// sequences once existed, so deleting index.idx must not turn
// ErrTruncated into ErrUnknownBatch.
//
// Layout, little-endian:
//
//	magic    6 bytes  "BCLTRN"
//	version  2 bytes  uint16
//	through  8 bytes  highest sequence reclaimed so far
//	segBound 8 bytes  highest segment file number reclaimed so far
//	crc32    4 bytes  IEEE checksum of every preceding byte
//
// The file is replaced atomically (fsynced temp + rename) before any
// segment file is removed, so a crash can only leave the previous
// marker or the new one, never a torn record. Open completes the file
// removal a persisted marker describes, hence a reopen after a crash
// mid-truncation sees either the complete old state or the complete
// new state.
var (
	truncateMagic   = []byte{'B', 'C', 'L', 'T', 'R', 'N'}
	truncateVersion = uint16(1)
)

type truncateMarker struct {
	through  uint64
	segBound uint64
}

const truncateFileLen = 6 + 2 + 8 + 8 + 4

func (l *Log) truncatePath() string {
	return filepath.Join(l.dir, "truncate.idx")
}

// encodeTruncateMarker serialises a truncation point with its trailing
// checksum.
func encodeTruncateMarker(m truncateMarker) []byte {
	buf := make([]byte, 0, truncateFileLen)
	buf = append(buf, truncateMagic...)
	var tmp [8]byte
	binary.LittleEndian.PutUint16(tmp[:2], truncateVersion)
	buf = append(buf, tmp[:2]...)
	binary.LittleEndian.PutUint64(tmp[:], m.through)
	buf = append(buf, tmp[:]...)
	binary.LittleEndian.PutUint64(tmp[:], m.segBound)
	buf = append(buf, tmp[:]...)
	binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(buf))
	return append(buf, tmp[:4]...)
}

// readTruncateMarker loads the truncation point. No marker (the common
// case for a log that has never been truncated) reports ok=false. A
// present but malformed marker is tampering, like any other framing
// inconsistency: ErrCorruptSegment.
func (l *Log) readTruncateMarker() (truncateMarker, bool, error) {
	path := l.truncatePath()
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return truncateMarker{}, false, nil
	}
	if err != nil {
		return truncateMarker{}, false, err
	}
	if len(data) != truncateFileLen ||
		string(data[:6]) != string(truncateMagic) ||
		binary.LittleEndian.Uint16(data[6:8]) != truncateVersion {
		return truncateMarker{}, false, ErrCorruptSegment
	}
	stored := binary.LittleEndian.Uint32(data[len(data)-4:])
	if crc32.ChecksumIEEE(data[:len(data)-4]) != stored {
		return truncateMarker{}, false, ErrCorruptSegment
	}
	// A stale temp file from a crash before the rename never replaces a
	// good marker; best effort cleanup.
	_ = os.Remove(path + ".tmp")
	return truncateMarker{
		through:  binary.LittleEndian.Uint64(data[8:16]),
		segBound: binary.LittleEndian.Uint64(data[16:24]),
	}, true, nil
}

// writeTruncateMarker durably replaces truncate.idx: the bytes land in
// a synced temp file first, then the rename makes the new point
// atomic. A lost rename leaves the previous marker in place, so the
// operation reads as the old state; syncing the directory is best
// effort and never required for correctness because Open converges.
func (l *Log) writeTruncateMarker(m truncateMarker) error {
	path := l.truncatePath()
	tmp := path + ".tmp"
	f, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}
	if _, err := f.Write(encodeTruncateMarker(m)); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := syncFile(f); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := f.Close(); err != nil {
		os.Remove(tmp)
		return err
	}
	if err := os.Rename(tmp, path); err != nil {
		os.Remove(tmp)
		return err
	}
	_ = syncDir(l.dir)
	return nil
}

// DeleteThrough reclaims the consumed prefix of the log. It removes
// whole segment files only: every complete segment whose highest
// reserved sequence (its last committed batch or its last hole
// marker, whichever is greater) is at or below seq is deleted, and
// the number of removed files is returned. Entries are never
// rewritten, and a batch or group is never split across the boundary:
// when seq falls in the middle of a segment, that segment is
// retained and the truncation stops one segment short.
//
// DeleteThrough(0) changes nothing and returns 0. seq must be a
// committed batch; otherwise — seq is unknown, a permanent hole,
// still staged, or a staged batch reserves a sequence at or below
// seq — DeleteThrough returns ErrInvalidRetention before touching
// anything. A call that finds no fully-reclaimable segment also
// changes nothing and returns 0.
//
// The truncation point is persisted (truncate.idx, atomically
// replaced) before any segment file is removed, so a crash leaves
// either the complete old state or the complete new state: a reopen
// finishes any pending file removal, and historical sequences keep
// reading as ErrTruncated even when index.idx is rebuilt from
// scratch. Idempotency keys that lived in deleted segments are
// released and may be reused; keys in retained segments keep their
// same-key dedup and different-key ErrBatchIDConflict.
func (l *Log) DeleteThrough(seq uint64) (int, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed {
		return 0, errClosed
	}
	if seq == 0 {
		return 0, nil
	}
	if _, ok := l.index[seq]; !ok {
		// Unknown, a permanent hole, or merely staged: only a sequence
		// with a committed batch may anchor a truncation.
		return 0, ErrInvalidRetention
	}
	// An uncommitted staged batch at or below seq would be reclaimed
	// together with the history it is logically still ahead of; its
	// reservation has to outlive the truncation.
	for s, recs := range l.staged {
		if recs != nil && s <= seq {
			return 0, ErrInvalidRetention
		}
	}

	physical, err := listSegmentNumbers(l.dir)
	if err != nil {
		return 0, err
	}
	boundOf := make(map[int]uint64, len(l.segs))
	for i := range l.segs {
		s := &l.segs[i]
		bound := uint64(0)
		if s.hasCommits {
			bound = s.LastSeq
		}
		if s.hasHoles && s.maxHole > bound {
			bound = s.maxHole
		}
		boundOf[s.file] = bound
	}
	// Segment files absent from l.segs are empty (a torn first entry
	// truncated to zero); their bound is 0. Take the contiguous prefix
	// whose every bound is at or below seq — the first segment that
	// overhangs seq ends the prefix, along with everything after it.
	var deleted []int
	for _, n := range physical {
		if boundOf[n] > seq {
			break
		}
		deleted = append(deleted, n)
	}
	if len(deleted) == 0 {
		return 0, nil
	}
	segBound := deleted[len(deleted)-1]
	retained := physical[len(deleted):]

	// 1) Durably commit the truncation point before removing anything.
	// A failure here leaves the full old state byte-for-byte.
	if err := l.writeTruncateMarker(truncateMarker{through: seq, segBound: uint64(segBound)}); err != nil {
		return 0, fmt.Errorf("%w: %v", ErrRetentionFailed, err)
	}

	// 2) Close the open current segment when it is being removed.
	currentDeleted := false
	for _, n := range deleted {
		if n == l.segIndex {
			currentDeleted = true
			break
		}
	}
	if currentDeleted && l.file != nil {
		l.file.Close()
		l.file = nil
		l.fileSize = 0
		// The next write opens segBound+1; segment numbers are never
		// reused, even when every file has been reclaimed. Reset the
		// write-side counters now so no later path can commit into the
		// stale segment view.
		l.segIndex = segBound
		l.curBatches = 0
	}

	// 3) Remove the old segment files. The marker already owns the
	// outcome: a failure converges on reopen, so keep going to reach
	// the complete new state in this process too.
	var firstErr error
	for _, n := range deleted {
		if err := removeFile(l.segmentPath(n)); err != nil && !os.IsNotExist(err) && firstErr == nil {
			firstErr = err
		}
	}
	_ = syncDir(l.dir)

	// 4) Rebuild the in-memory view from exactly the retained files,
	// preserving live staged batches (all of which reserve sequences
	// above seq, checked above) and their keys. Scanning also recovers
	// a torn tail of the last retained segment as usual.
	live := make(map[uint64][][]byte)
	liveIDs := make(map[uint64]string)
	for s, recs := range l.staged {
		if recs != nil {
			live[s] = recs
			if id := l.stagedID[s]; id != "" {
				liveIDs[s] = id
			}
		}
	}
	// Retained batches keep their original publication generations, so
	// a Scan snapshot taken before the truncation keeps seeing exactly
	// the retained batches it could already see (their files survive),
	// while every post-truncation commit lands above oldGen and stays
	// invisible to it — the same snapshot guarantee as always.
	oldGen := l.gen
	oldGenBySeq := make(map[uint64]uint64, len(l.index))
	for s, ref := range l.index {
		oldGenBySeq[s] = ref.gen
	}
	p, scanErr := l.scanSegments(retained)
	if scanErr != nil {
		// The retained files are unreadable: do not adopt a partial
		// view. The old state is already partly deleted on disk, but the
		// durable marker makes the outcome converge on the next open;
		// surface the failure and leave index state untouched.
		return len(deleted), fmt.Errorf("%w: %v", ErrRetentionFailed, scanErr)
	}
	l.index = make(map[uint64]entryRef)
	l.ids = make(map[string]uint64)
	l.staged = make(map[uint64][][]byte)
	l.stagedID = make(map[uint64]string)
	l.segs = nil
	l.gen = 0
	l.nextSeq = 1
	l.through = seq
	if err := l.installSnapshot(p, retained); err != nil && firstErr == nil {
		firstErr = err
	}
	for s := range l.index {
		if g, ok := oldGenBySeq[s]; ok {
			ref := l.index[s]
			ref.gen = g
			l.index[s] = ref
		}
	}
	// Generations are an in-process monotonic counter; resume after the
	// highest generation ever handed out so new commits never collide
	// with a pre-truncation snapshot.
	l.gen = oldGen
	for s, recs := range live {
		l.staged[s] = recs
		if id := liveIDs[s]; id != "" {
			l.stagedID[s] = id
			// A staged keyed batch survives the truncation; its key
			// must keep resolving to its reserved sequence for retries.
			l.ids[id] = s
		}
		if s >= l.nextSeq {
			l.nextSeq = s + 1
		}
	}

	// 5) Replace the sidecar with a snapshot of the retained segments
	// and reopen the live append handle. A failure here does not lose
	// data: the retained files are the source of truth and a stale or
	// missing sidecar is rebuilt on the next open. The process keeps
	// serving from the in-memory view just installed.
	if l.idxFile != nil {
		l.idxFile.Close()
		l.idxFile = nil
	}
	if err := l.writeIndexSnapshot(p); err != nil && firstErr == nil {
		firstErr = err
	}
	if err := l.openIndex(); err != nil && firstErr == nil {
		firstErr = err
	}
	if firstErr != nil {
		return len(deleted), fmt.Errorf("%w: %v", ErrRetentionFailed, firstErr)
	}
	return len(deleted), nil
}

// listSegmentNumbers returns the numeric names of the *.seg files in
// dir, sorted ascending.
func listSegmentNumbers(dir string) ([]int, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var nums []int
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".seg") {
			continue
		}
		n, err := strconv.Atoi(strings.TrimSuffix(e.Name(), ".seg"))
		if err != nil {
			continue
		}
		nums = append(nums, n)
	}
	sort.Ints(nums)
	return nums, nil
}

package log

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"os"
	"sort"
	"unicode/utf8"
)

// The segment-level index lives in a sidecar file ("index.idx") next to
// the segments so that Open never has to decode every segment entry as
// the log grows. The sidecar is a derived, rebuildable cache: losing
// it, or finding it truncated, version-mismatched, checksum-bad or
// contradictory to the segments, only triggers a full rebuild from the
// segment files — never data loss and never a user-visible error.
//
// Layout, all integers little-endian:
//
//	header  8 bytes  "BCLIDX" (6 bytes) + uint16 version
//	records          length-prefixed, checksummed, in (segment, offset)
//	                 order:
//
//	  committed entry ("E"):
//	    8 bytes segment file number
//	    8 bytes offset of the entry's segment magic
//	    8 bytes length of the whole entry on disk (magic ... crc)
//	    4 bytes disk entry CRC (the checksum stored by the segment)
//	    4 bytes member count m
//	    1 byte  flags (bit 0: entry uses keyed framing — BCLI/BCLK)
//	    m × (8-byte seq, 8-byte body offset, 4-byte body length,
//	         2-byte key length, key bytes; key length 0 = anonymous)
//
// Version 1 sidecars (no flags byte and no key fields) are not
// interpreted: a version mismatch triggers the ordinary one-time rebuild
// from the segment files, exactly like any other invalid sidecar.
//
//	hole marker ("H"):
//	  8 bytes segment file number
//	  8 bytes offset of the marker's segment magic
//	  8 bytes length of the whole marker on disk
//	  4 bytes disk marker CRC
//	  4 bytes sequence count c
//	  c × 8-byte sequence
//
// Every record is framed as: 1-byte type, 4-byte body length, body,
// 4-byte CRC32 of type+length+body. A torn final record — the remnant
// of a crash between the index write and its sync — is discarded on the
// next open, and any such truncation makes Open rebuild from the
// segments instead. Records are appended only after the corresponding
// segment entry is durable, so an adopted index can never advertise a
// batch the segments do not contain; adoption re-verifies the physical
// layout and every disk CRC before trusting it.
var (
	indexMagic   = []byte{'B', 'C', 'L', 'I', 'D', 'X'}
	indexVersion = uint16(2)

	recEntry = byte('E')
	recHole  = byte('H')

	// entryFlagKeyed marks an E record whose segment entry uses keyed
	// framing (BCLI for a lone keyed commit, BCLK for a group containing
	// at least one keyed member).
	entryFlagKeyed = byte(1)
)

// indexEntry is one committed segment entry: either a single batch or a
// whole group, located on disk and carrying every member's index ref.
type indexEntry struct {
	seg     int
	off     int // offset of the entry's segment magic
	length  int // total length of the entry on disk, including its CRC
	diskCRC uint32
	keyed   bool // segment entry is BCLI/BCLK rather than BCL1/BCLG
	members []indexMember
}

type indexMember struct {
	seq    uint64
	id     string // idempotency key, "" for an anonymous member
	off    int    // body offset within the segment file
	length int    // body length
}

// indexHole is one durable BCLH marker on disk.
type indexHole struct {
	seg     int
	off     int
	length  int
	diskCRC uint32
	seqs    []uint64
}

type parsedIndex struct {
	entries []indexEntry
	holes   []indexHole
}

var errIndexInvalid = errors.New("log: invalid index sidecar")

// readIndexFile parses the sidecar bytes strictly. A truncated final
// record — the remnant of a crash between an index write and its sync —
// is reported as tailLen (the valid prefix length). Missing tail bytes
// are the only tolerated defect; bad framing, an unknown version or any
// checksum mismatch yield errIndexInvalid.
func readIndexFile(data []byte) (p parsedIndex, tailLen int, err error) {
	const headerLen = 8
	if len(data) < headerLen {
		return parsedIndex{}, 0, errIndexInvalid
	}
	if string(data[:6]) != string(indexMagic) {
		return parsedIndex{}, 0, errIndexInvalid
	}
	if binary.LittleEndian.Uint16(data[6:8]) != indexVersion {
		return parsedIndex{}, 0, errIndexInvalid
	}
	pos := headerLen
	for pos < len(data) {
		start := pos
		rest := data[pos:]
		if len(rest) < 10 {
			// type(1) + length(4) + crc(4) is the smallest record.
			return p, start, nil
		}
		kind := rest[0]
		bodyLen := int(binary.LittleEndian.Uint32(rest[1:5]))
		if bodyLen < 0 {
			return parsedIndex{}, 0, errIndexInvalid
		}
		total := 5 + bodyLen + 4 // type + length + body + crc
		if len(data)-start < total {
			// Any truncation of the last record is a crash tail.
			return p, start, nil
		}
		body := rest[5 : 5+bodyLen]
		crc := binary.LittleEndian.Uint32(rest[5+bodyLen : 9+bodyLen])
		if crc32.ChecksumIEEE(rest[:5+bodyLen]) != crc {
			return parsedIndex{}, 0, errIndexInvalid
		}
		bp := 0
		switch kind {
		case recEntry:
			const fixed = 8 + 8 + 8 + 4 + 4 + 1
			if bodyLen < fixed {
				return parsedIndex{}, 0, errIndexInvalid
			}
			e := indexEntry{}
			e.seg = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			e.off = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			e.length = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			e.diskCRC = binary.LittleEndian.Uint32(body[bp : bp+4])
			bp += 4
			m := int(binary.LittleEndian.Uint32(body[bp : bp+4]))
			bp += 4
			flags := body[bp]
			bp++
			if flags & ^entryFlagKeyed != 0 {
				return parsedIndex{}, 0, errIndexInvalid
			}
			e.keyed = flags&entryFlagKeyed != 0
			if m <= 0 {
				return parsedIndex{}, 0, errIndexInvalid
			}
			e.members = make([]indexMember, m)
			for i := 0; i < m; i++ {
				if bodyLen-bp < 8+8+4+2 {
					return parsedIndex{}, 0, errIndexInvalid
				}
				mb := indexMember{
					seq:    binary.LittleEndian.Uint64(body[bp : bp+8]),
					off:    int(binary.LittleEndian.Uint64(body[bp+8 : bp+16])),
					length: int(binary.LittleEndian.Uint32(body[bp+16 : bp+20])),
				}
				bp += 20
				klen := int(binary.LittleEndian.Uint16(body[bp : bp+2]))
				bp += 2
				if !e.keyed && klen != 0 {
					return parsedIndex{}, 0, errIndexInvalid
				}
				if klen < 0 || klen > maxBatchIDLen || bodyLen-bp < klen {
					return parsedIndex{}, 0, errIndexInvalid
				}
				if klen > 0 {
					raw := body[bp : bp+klen]
					if bytes.IndexByte(raw, 0) >= 0 || !utf8.Valid(raw) {
						return parsedIndex{}, 0, errIndexInvalid
					}
					mb.id = string(raw)
					bp += klen
				}
				e.members[i] = mb
			}
			if bp != bodyLen {
				return parsedIndex{}, 0, errIndexInvalid
			}
			if e.seg <= 0 || e.off < 0 || e.length <= 0 {
				return parsedIndex{}, 0, errIndexInvalid
			}
			p.entries = append(p.entries, e)
		case recHole:
			if bodyLen < 8+8+8+4+4 {
				return parsedIndex{}, 0, errIndexInvalid
			}
			h := indexHole{}
			h.seg = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			h.off = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			h.length = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			h.diskCRC = binary.LittleEndian.Uint32(body[bp : bp+4])
			bp += 4
			c := int(binary.LittleEndian.Uint32(body[bp : bp+4]))
			bp += 4
			if h.seg <= 0 || h.off < 0 || h.length <= 0 || c < 0 || 8*c != bodyLen-bp {
				return parsedIndex{}, 0, errIndexInvalid
			}
			h.seqs = make([]uint64, c)
			for i := 0; i < c; i++ {
				h.seqs[i] = binary.LittleEndian.Uint64(body[bp : bp+8])
				bp += 8
			}
			p.holes = append(p.holes, h)
		default:
			return parsedIndex{}, 0, errIndexInvalid
		}
		pos = start + total
	}
	return p, 0, nil
}

// encodeIndexHeader returns the sidecar header.
func encodeIndexHeader() []byte {
	buf := make([]byte, 0, 8)
	buf = append(buf, indexMagic...)
	var tmp [8]byte
	binary.LittleEndian.PutUint16(tmp[:2], indexVersion)
	return append(buf, tmp[:2]...)
}

// finishIndexRecord wraps a record body with its type tag, length and
// trailing checksum.
func finishIndexRecord(kind byte, body []byte) []byte {
	rec := make([]byte, 0, 5+len(body)+4)
	rec = append(rec, kind)
	var tmp [8]byte
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(body)))
	rec = append(rec, tmp[:4]...)
	rec = append(rec, body...)
	binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(rec))
	return append(rec, tmp[:4]...)
}

func putIndexU64(body *[]byte, tmp *[8]byte, v uint64) {
	binary.LittleEndian.PutUint64(tmp[:], v)
	*body = append(*body, tmp[:]...)
}

// encodeEntryRecord encodes one committed segment entry and its members.
func encodeEntryRecord(e indexEntry) []byte {
	size := 8 + 8 + 8 + 4 + 4 + 1
	for _, m := range e.members {
		size += 8 + 8 + 4 + 2 + len(m.id)
	}
	body := make([]byte, 0, size)
	var tmp [8]byte
	putIndexU64(&body, &tmp, uint64(e.seg))
	putIndexU64(&body, &tmp, uint64(e.off))
	putIndexU64(&body, &tmp, uint64(e.length))
	binary.LittleEndian.PutUint32(tmp[:4], e.diskCRC)
	body = append(body, tmp[:4]...)
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(e.members)))
	body = append(body, tmp[:4]...)
	flags := byte(0)
	if e.keyed {
		flags = entryFlagKeyed
	}
	body = append(body, flags)
	for _, m := range e.members {
		putIndexU64(&body, &tmp, m.seq)
		putIndexU64(&body, &tmp, uint64(m.off))
		binary.LittleEndian.PutUint32(tmp[:4], uint32(m.length))
		body = append(body, tmp[:4]...)
		binary.LittleEndian.PutUint16(tmp[:2], uint16(len(m.id)))
		body = append(body, tmp[:2]...)
		body = append(body, m.id...)
	}
	return finishIndexRecord(recEntry, body)
}

// encodeHoleRecord encodes one durable hole marker as seen in a segment.
func encodeHoleRecord(h indexHole) []byte {
	body := make([]byte, 0, 8+8+8+4+4+8*len(h.seqs))
	var tmp [8]byte
	putIndexU64(&body, &tmp, uint64(h.seg))
	putIndexU64(&body, &tmp, uint64(h.off))
	putIndexU64(&body, &tmp, uint64(h.length))
	binary.LittleEndian.PutUint32(tmp[:4], h.diskCRC)
	body = append(body, tmp[:4]...)
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(h.seqs)))
	body = append(body, tmp[:4]...)
	for _, seq := range h.seqs {
		putIndexU64(&body, &tmp, seq)
	}
	return finishIndexRecord(recHole, body)
}

// diskRecord is one physical on-disk item located by the index, merged
// in (segment, offset) order for the canonical snapshot.
type diskRecord struct {
	seg int
	off int
	enc []byte
}

// writeIndexSnapshot replaces the sidecar atomically with a full image
// of the recovered log: the header, then every committed entry and hole
// marker in (segment, offset) order. The temp file is fsynced before
// the rename; callers run this after the segment bytes it describes are
// synced. A lost rename only leaves the previous sidecar behind, which
// adoption validation rejects as contradictory, triggering a rebuild.
func (l *Log) writeIndexSnapshot(p parsedIndex) error {
	var recs []diskRecord
	for i := range p.entries {
		e := &p.entries[i]
		recs = append(recs, diskRecord{seg: e.seg, off: e.off, enc: encodeEntryRecord(*e)})
	}
	for i := range p.holes {
		h := &p.holes[i]
		recs = append(recs, diskRecord{seg: h.seg, off: h.off, enc: encodeHoleRecord(*h)})
	}
	sort.SliceStable(recs, func(i, j int) bool {
		if recs[i].seg != recs[j].seg {
			return recs[i].seg < recs[j].seg
		}
		return recs[i].off < recs[j].off
	})
	var buf []byte
	buf = append(buf, encodeIndexHeader()...)
	for _, r := range recs {
		buf = append(buf, r.enc...)
	}
	tmp := l.indexPath() + ".tmp"
	f, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}
	if _, err := f.Write(buf); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := syncFile(f); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := f.Close(); err != nil {
		os.Remove(tmp)
		return err
	}
	if err := os.Rename(tmp, l.indexPath()); err != nil {
		os.Remove(tmp)
		return err
	}
	// Best effort: if the rename is not journaled and power loss keeps
	// the previous sidecar, adoption validation detects the divergence
	// and rebuilds, so snapshot correctness never depends on this sync.
	_ = syncDir(l.dir)
	return nil
}

// appendIndexRecord appends one record to the live sidecar after a
// commit's segment entry is durable. With Options.Sync it fsyncs the
// sidecar before returning. Any failure is returned to the caller,
// which rolls the just-written segment entry and this record back; an
// fsync failure is wrapped as ErrSyncFailed so commits keep their
// documented error semantics.
func (l *Log) appendIndexRecord(rec []byte) error {
	if l.idxFile == nil {
		return errIndexInvalid
	}
	if _, err := l.idxFile.Write(rec); err != nil {
		return err
	}
	l.idxSize += len(rec)
	if l.opts.Sync {
		if err := syncFile(l.idxFile); err != nil {
			return fmt.Errorf("%w: %v", ErrSyncFailed, err)
		}
	}
	return nil
}

// truncateIndex rolls the sidecar back to size n after a failed commit,
// mirroring the segment-entry rollback so no uncommitted record is left
// behind and a retry cannot duplicate it.
func (l *Log) truncateIndex(n int) {
	if l.idxFile == nil {
		return
	}
	if err := l.idxFile.Truncate(int64(n)); err != nil {
		// Best effort: an untidy sidecar is harmless. Open never trusts
		// it blindly and rebuilds from the segments on any contradiction.
		return
	}
	l.idxSize = n
}

// openIndex opens the live sidecar for append, creating it absent. The
// file has already been validated (or freshly snapshotted) by Open; an
// empty file (a log with no commits yet) gets its header first.
func (l *Log) openIndex() error {
	f, err := os.OpenFile(l.indexPath(), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		return err
	}
	st, err := f.Stat()
	if err != nil {
		f.Close()
		return err
	}
	l.idxFile = f
	l.idxSize = int(st.Size())
	if l.idxSize == 0 {
		hdr := encodeIndexHeader()
		if _, err := f.Write(hdr); err != nil {
			f.Close()
			l.idxFile = nil
			return err
		}
		l.idxSize = len(hdr)
	}
	return nil
}

// readIndexBytes reads the whole sidecar. Used only by adoption.
func (l *Log) readIndexBytes() ([]byte, error) {
	f, err := os.Open(l.indexPath())
	if err != nil {
		return nil, err
	}
	defer f.Close()
	return io.ReadAll(f)
}

// Command logctl inspects a batch-commit log directory.
//
//	logctl --dir <path> stat
//
// stat prints one compact JSON line summarising the directory:
//
//	{"segments":2,"firstSeq":1,"lastSeq":7}
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"

	bcl "github.com/Hulalalalalalalalalalala/batch-commit-log"
)

func main() {
	fs := flag.NewFlagSet("logctl", flag.ExitOnError)
	dir := fs.String("dir", "", "path to the log directory")
	fs.Parse(os.Args[1:])
	if *dir == "" || fs.NArg() != 1 || fs.Arg(0) != "stat" {
		fmt.Fprintln(os.Stderr, "usage: logctl --dir <path> stat")
		os.Exit(2)
	}

	l, err := bcl.Open(*dir, bcl.Options{SegmentBytes: 64 << 20})
	if err != nil {
		fmt.Fprintln(os.Stderr, "logctl:", err)
		os.Exit(1)
	}
	defer l.Close()

	segs := l.Segments()
	var first, last uint64
	for i, s := range segs {
		if i == 0 || s.FirstSeq < first {
			first = s.FirstSeq
		}
		if i == 0 || s.LastSeq > last {
			last = s.LastSeq
		}
	}
	out := struct {
		Segments int    `json:"segments"`
		FirstSeq uint64 `json:"firstSeq"`
		LastSeq  uint64 `json:"lastSeq"`
	}{Segments: len(segs), FirstSeq: first, LastSeq: last}
	line, err := json.Marshal(out)
	if err != nil {
		fmt.Fprintln(os.Stderr, "logctl:", err)
		os.Exit(1)
	}
	fmt.Println(string(line))
}

