	synced = nil
	if err := l.AckConsumer("c", s1); err != nil {
		t.Fatalf("retry ack: %v", err)
	}
	if got, _ := l.ConsumerSeq("c"); got != s1 {
		t.Fatalf("point = %d, want %d", got, s1)
	}

