// syncSegmentsThrough fsyncs every surviving segment file at or before
// seg that has not been fsynced by an acknowledgement already, so that
// when Sync is false a returned acknowledgement still guarantees the
// target batch and every committed byte before it durable. Segment
// files are immutable once rolled, so each file number needs this at
// most once per process; ackSyncedSeg records the high-water mark.
func (l *Log) syncSegmentsThrough(seg int) error {
	for i := range l.segs {
		s := &l.segs[i]
		if s.file > seg {
			break
		}
		if uint64(s.file) <= l.ackSyncedSeg {
			continue
		}
		if err := l.fsyncSegmentFile(s.file); err != nil {
			return err
		}
		l.ackSyncedSeg = uint64(s.file)
	}
	return nil
}

// fsyncSegmentFile fsyncs one segment, using the live append handle
// for the current segment and opening older, sealed files read-only.
func (l *Log) fsyncSegmentFile(n int) error {
	if l.file != nil && n == l.segIndex {
		return syncFile(l.file)
	}
	f, err := os.Open(l.segmentPath(n))
	if err != nil {
		return err
	}
	defer f.Close()
	return syncFile(f)
}

